import 'package:flutter/material.dart';
import '../app.dart';

class QrAttendanceScreen extends StatefulWidget { const QrAttendanceScreen({super.key}); @override State<QrAttendanceScreen> createState()=>_QrAttendanceScreenState(); }
class _QrAttendanceScreenState extends State<QrAttendanceScreen>{ final branchId=TextEditingController(); final memberId=TextEditingController(); final token=TextEditingController(); String result=''; @override Widget build(BuildContext context){ final api=AppScope.of(context).api; return Scaffold(appBar: AppBar(title: const Text('QR Attendance')), body: ListView(padding: const EdgeInsets.all(16), children:[TextField(controller: branchId, decoration: const InputDecoration(labelText:'Branch ID')), TextField(controller: memberId, decoration: const InputDecoration(labelText:'Member ID')), TextField(controller: token, decoration: const InputDecoration(labelText:'QR Token')), const SizedBox(height:16), FilledButton(onPressed:() async { final response=await api.post('/attendance/qr-check-in', {'branchId':branchId.text,'memberId':memberId.text,'token':token.text}); setState(()=>result=response.toString()); }, child: const Text('Check In')), Text(result)])); }}
